/// Operit1 caches the last tool, system block, and cacheable message block.
/// The persisted cache_control model parameter selects the actual block TTL.
pub fn apply_stable_cache_breakpoints(&self, request_object: &mut Map<String, Value>) {
    let cache_control = request_object.remove("cache_control")
        .unwrap_or_else(|| json!({"type": "ephemeral"}));
    // Do not also send automatic top-level caching: its final breakpoint can
    // conflict with explicit blocks, especially if their TTLs differ.
    for key in ["tools", "system"] {
        if let Some(block) = request_object.get_mut(key)
            .and_then(Value::as_array_mut)
            .and_then(|blocks| blocks.iter_mut().rev().find_map(Value::as_object_mut)) {
            block.entry("cache_control".to_string()).or_insert_with(|| cache_control.clone());
        }
    }
    if let Some(messages) = request_object.get_mut("messages").and_then(Value::as_array_mut) {
        for message in messages.iter_mut().rev() {
            let Some(content) = message.get_mut("content").and_then(Value::as_array_mut) else { continue; };
            for value in content.iter_mut().rev() {
                let Some(block) = value.as_object_mut() else { continue; };
                // Thinking blocks cannot be explicit cache targets.
                if matches!(block.get("type").and_then(Value::as_str), Some("thinking" | "redacted_thinking")) { continue; }
                if block.get("type").and_then(Value::as_str) == Some("text")
                    && block.get("text").and_then(Value::as_str).is_some_and(|text| text.is_empty()) { continue; }
                block.entry("cache_control".to_string()).or_insert_with(|| cache_control.clone());
                return;
            }
        }
    }
}

